import Foundation
import CryptoKit

// Circuit Breaker States
enum CircuitState {
    case closed
    case open
    case halfOpen
}

class CircuitBreaker {
    private var failureCount: Int = 0
    private var successCount: Int = 0
    private var lastFailureTime: Date?
    private var state: CircuitState = .closed
    private let failureThreshold: Int
    private let recoveryTimeout: TimeInterval
    private let successThreshold: Int
    private let lock = NSLock()

    init(failureThreshold: Int = 5, recoveryTimeout: TimeInterval = 30.0, successThreshold: Int = 3) {
        self.failureThreshold = failureThreshold
        self.recoveryTimeout = recoveryTimeout
        self.successThreshold = successThreshold
    }

    func currentState() -> CircuitState {
        lock.lock()
        defer { lock.unlock() }

        if state == .open {
            if let lastFailure = lastFailureTime,
               Date().timeIntervalSince(lastFailure) >= recoveryTimeout {
                state = .halfOpen
                successCount = 0
            }
        }
        return state
    }

    func recordSuccess() {
        lock.lock()
        defer { lock.unlock() }

        if state == .halfOpen {
            successCount += 1
            if successCount >= successThreshold {
                state = .closed
                failureCount = 0
                successCount = 0
            }
        } else if state == .closed {
            failureCount = 0
        }
    }

    func recordFailure() {
        lock.lock()
        defer { lock.unlock() }

        failureCount += 1
        lastFailureTime = Date()

        if state == .halfOpen {
            state = .open
        } else if failureCount >= failureThreshold {
            state = .open
        }
    }

    func shouldAllowRequest() -> Bool {
        let current = currentState()
        switch current {
        case .closed:
            return true
        case .open:
            return false
        case .halfOpen:
            return true
        }
    }
}

class AuthenticationService {
    private var circuitBreakers: [String: CircuitBreaker] = [:]
    private let globalCircuitBreaker = CircuitBreaker(failureThreshold: 50, recoveryTimeout: 60.0)
    private var ipCircuitBreakers: [String: CircuitBreaker] = [:]
    private let lock = NSLock()

    private func getBreaker(forUser username: String) -> CircuitBreaker {
        lock.lock()
        defer { lock.unlock() }

        if let breaker = circuitBreakers[username] {
            return breaker
        }
        let breaker = CircuitBreaker(failureThreshold: 5, recoveryTimeout: 30.0)
        circuitBreakers[username] = breaker
        return breaker
    }

    private func getIPBreaker(forIP ip: String) -> CircuitBreaker {
        lock.lock()
        defer { lock.unlock() }

        if let breaker = ipCircuitBreakers[ip] {
            return breaker
        }
        let breaker = CircuitBreaker(failureThreshold: 10, recoveryTimeout: 60.0)
        ipCircuitBreakers[ip] = breaker
        return breaker
    }

    func authenticate(username: String, password: String, sourceIP: String) -> (success: Bool, message: String) {
        // Check global rate limit
        guard globalCircuitBreaker.shouldAllowRequest() else {
            return (false, "Service temporarily unavailable. Too many failed attempts globally.")
        }

        // Check per-IP rate limit
        let ipBreaker = getIPBreaker(forIP: sourceIP)
        guard ipBreaker.shouldAllowRequest() else {
            return (false, "Too many attempts from this IP address.")
        }

        // Get per-user circuit breaker
        let userBreaker = getBreaker(forUser: username)

        guard userBreaker.shouldAllowRequest() else {
            return (false, "Account temporarily locked due to too many failed attempts.")
        }

        // Perform authentication
        let result = verifyCredentials(username: username, password: password)

        if result {
            userBreaker.recordSuccess()
            globalCircuitBreaker.recordSuccess()
            ipBreaker.recordSuccess()
            return (true, "Authentication successful.")
        } else {
            userBreaker.recordFailure()
            globalCircuitBreaker.recordFailure()
            ipBreaker.recordFailure()
            return (false, "Invalid credentials.")
        }
    }

