// CLI Entry Point
func main() {
    let service = AuthenticationService()
    let args = CommandLine.arguments

    guard args.count >= 4 else {
        print("Usage: auth-cli <username> <password> <source-ip>")
        return
    }

    let username = args[1]
    let password = args[2]
    let sourceIP = args[3]

    // Normalize username for consistent circuit breaker lookup
    let normalizedUsername = username.lowercased().trimmingCharacters(in: .whitespaces)

    let result = service.authenticate(username: normalizedUsername, password: password, sourceIP: sourceIP)

